CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, slug TEXT UNIQUE, data TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created INTEGER, updated INTEGER);
CREATE TABLE IF NOT EXISTS settings (id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS claims (token TEXT PRIMARY KEY, created INTEGER NOT NULL, used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, request_key TEXT NOT NULL UNIQUE, user_id TEXT, name TEXT NOT NULL, email TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL, contact_preference TEXT NOT NULL DEFAULT 'either', alternative_phone TEXT NOT NULL DEFAULT '', delivery_address TEXT NOT NULL DEFAULT '', city TEXT NOT NULL DEFAULT '', note TEXT NOT NULL, internal_notes TEXT NOT NULL DEFAULT '', product_id TEXT NOT NULL, product_name TEXT NOT NULL, subtotal INTEGER NOT NULL, discount INTEGER NOT NULL, total INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'new', created INTEGER NOT NULL, updated INTEGER NOT NULL, synced INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS orders_phone_idx ON orders(phone);
CREATE INDEX IF NOT EXISTS orders_user_idx ON orders(user_id);
CREATE TABLE IF NOT EXISTS rates (key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS audit (id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS loyalty_offers (code TEXT PRIMARY KEY, phone TEXT NOT NULL, percent INTEGER NOT NULL, minimum INTEGER NOT NULL DEFAULT 0, expires INTEGER NOT NULL, used_order TEXT, active INTEGER NOT NULL DEFAULT 1, created INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS loyalty_phone_idx ON loyalty_offers(phone);
CREATE TABLE IF NOT EXISTS media (id TEXT PRIMARY KEY, url TEXT NOT NULL, storage_key TEXT NOT NULL, mime TEXT NOT NULL, size INTEGER NOT NULL, name TEXT NOT NULL, created INTEGER NOT NULL, updated INTEGER NOT NULL);
